INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_prir-3-ptaci-nase-prirody_0','Který pták hnízdí na komíně?',ARRAY['sova','kos','čáp','datel']::TEXT[],2,'Čáp bílý staví hnízdo na komínech a střechách.',1,ARRAY[]::TEXT[],NULL,0,'c_prir-3-ptaci-nase-prirody',NULL,NOW()),
('q_prir-3-ptaci-nase-prirody_1','Který pták ukazuje příchod jara a stěhuje se do teplých krajů?',ARRAY['vlaštovka','vrabec','holub','sýkora']::TEXT[],0,'Vlaštovka je stěhovavý pták.',1,ARRAY[]::TEXT[],NULL,1,'c_prir-3-ptaci-nase-prirody',NULL,NOW()),
('q_prir-3-ptaci-nase-prirody_2','Který pták loví v noci?',ARRAY['sova','kos','vlaštovka','vrabec']::TEXT[],0,'Sova je noční dravec.',1,ARRAY[]::TEXT[],NULL,2,'c_prir-3-ptaci-nase-prirody',NULL,NOW()),
('q_prir-3-ptaci-nase-prirody_3','Který pták vyklepává dutiny do stromů?',ARRAY['datel','labuť','holub','čáp']::TEXT[],0,'Datel (strakapoud) vyklepává dutiny.',2,ARRAY[]::TEXT[],NULL,3,'c_prir-3-ptaci-nase-prirody',NULL,NOW()),
('q_prir-3-ptaci-nase-prirody_4','Který pták klade vajíčka do cizích hnízd?',ARRAY['kukačka','sýkora','vrabec','kos']::TEXT[],0,'Kukačka podstrkuje vejce jiným ptákům.',2,ARRAY[]::TEXT[],NULL,4,'c_prir-3-ptaci-nase-prirody',NULL,NOW()),
('q_prir-3-ptaci-nase-prirody_5','Který velký bílý pták plave na rybníce s dlouhým krkem?',ARRAY['kachna','holub','labuť','vrabec']::TEXT[],2,'Labuť má dlouhý krk.',2,ARRAY[]::TEXT[],NULL,5,'c_prir-3-ptaci-nase-prirody',NULL,NOW()),
('q_prir-3-ptaci-nase-prirody_6','Jak se jmenuje pták, který ráno zpívá a je černý se žlutým zobákem?',ARRAY['vrabec','datel','čáp','kos']::TEXT[],3,'Kos černý.',3,ARRAY[]::TEXT[],NULL,6,'c_prir-3-ptaci-nase-prirody',NULL,NOW()),
('q_prir-3-ptaci-nase-prirody_7','Čím se živí vlaštovka?',ARRAY['semeny','rybami','létajícím hmyzem','trávou']::TEXT[],2,'Vlaštovka loví hmyz za letu.',3,ARRAY[]::TEXT[],NULL,7,'c_prir-3-ptaci-nase-prirody',NULL,NOW()),
('q_prir-3-ptaci-nase-prirody_8','Který malý pták nejčastěji navštěvuje v zimě krmítko na zahradě?',ARRAY['čáp','kukačka','sýkora','labuť']::TEXT[],2,'Sýkory navštěvují krmítka.',3,ARRAY[]::TEXT[],NULL,8,'c_prir-3-ptaci-nase-prirody',NULL,NOW()),
('q_prir-3-ptaci-nase-prirody_9','Který pták je dravec ve dne?',ARRAY['sýkora','labuť','káně','kos']::TEXT[],2,'Káně lesní je denní dravec.',4,ARRAY[]::TEXT[],NULL,9,'c_prir-3-ptaci-nase-prirody',NULL,NOW()),
('q_prir-3-ptaci-nase-prirody_10','Co dělají stěhovaví ptáci na podzim?',ARRAY['usínají zimním spánkem','odlétají do teplých krajů','zahrabávají se do země','mění peří na srst']::TEXT[],1,'Stěhovaví ptáci odlétají na zimu.',4,ARRAY[]::TEXT[],NULL,10,'c_prir-3-ptaci-nase-prirody',NULL,NOW()),
('q_prir-3-ptaci-nase-prirody_11','K čemu slouží ptačí peří?',ARRAY['k rytí v zemi','k dýchání','k letu a udržení tepla','k plavání pod vodou']::TEXT[],2,'Peří umožňuje let a hřeje.',4,ARRAY[]::TEXT[],NULL,11,'c_prir-3-ptaci-nase-prirody',NULL,NOW()),
('q_prir-3-ptaci-nase-prirody_12','Který pták nemůže létat, ale rychle běhá?',ARRAY['orel','čáp','kachna','pštros']::TEXT[],3,'Pštros je největší pták a nelétá.',5,ARRAY[]::TEXT[],NULL,12,'c_prir-3-ptaci-nase-prirody',NULL,NOW()),
('q_prir-3-ptaci-nase-prirody_13','Kolik nohou má pták?',ARRAY['čtyři','šest','osm','dvě']::TEXT[],3,'Ptáci mají dvě nohy.',5,ARRAY[]::TEXT[],NULL,13,'c_prir-3-ptaci-nase-prirody',NULL,NOW()),
